import { z } from "zod";
import { BaseTool } from "../utils/base-tool.js";
import { readdir } from "fs/promises";
import { join } from "path";
const READ_FILE_TOOL_NAME = "read-file-21";
const READ_FILE_DESCRIPTION = "Activate this tool when /21 is mentioned in the message, it transports file to 21st";
export class ReadFileTool extends BaseTool {
    constructor() {
        super(...arguments);
        this.name = READ_FILE_TOOL_NAME;
        this.description = READ_FILE_DESCRIPTION;
        this.schema = z.object({
            absolutePathToProjectDirectory: z
                .string()
                .describe("Path to the project root directory"),
        });
    }
    async execute({ absolutePathToProjectDirectory, }) {
        try {
            const cwd = absolutePathToProjectDirectory;
            const currentDirFiles = await readdir(absolutePathToProjectDirectory, {
                withFileTypes: true,
            });
            const parentDirFiles = await readdir(join(cwd, ".."), {
                withFileTypes: true,
            });
            const diagnostics = {
                cwd,
                currentDirectory: currentDirFiles.map((entry) => ({
                    name: entry.name,
                    type: entry.isDirectory() ? "directory" : "file",
                })),
                parentDirectory: parentDirFiles.map((entry) => ({
                    name: entry.name,
                    type: entry.isDirectory() ? "directory" : "file",
                })),
                platform: process.platform,
                env: process.env.NODE_ENV,
                apiKeyProvided: !!this.apiKey,
                params: this.params,
            };
            // const content = await readFile(absolutePathToProjectRoot, "utf-8");
            return {
                content: [
                    {
                        type: "text",
                        text: JSON.stringify({
                            diagnostics,
                        }, null, 2),
                    },
                ],
            };
        }
        catch (error) {
            return {
                content: [
                    {
                        type: "text",
                        text: JSON.stringify({
                            error: {
                                message: error.message,
                                code: error.code,
                                path: error.path,
                                diagnostics: {
                                    cwd: process.cwd(),
                                    currentDirectory: await readdir(process.cwd(), {
                                        withFileTypes: true,
                                    }).then((files) => files.map((entry) => ({
                                        name: entry.name,
                                        type: entry.isDirectory() ? "directory" : "file",
                                    }))),
                                    parentDirectory: await readdir(join(process.cwd(), ".."), {
                                        withFileTypes: true,
                                    }).then((files) => files.map((entry) => ({
                                        name: entry.name,
                                        type: entry.isDirectory() ? "directory" : "file",
                                    }))),
                                    platform: process.platform,
                                    apiKeyProvided: !!this.apiKey,
                                },
                            },
                        }, null, 2),
                    },
                ],
            };
        }
    }
}
